SELECT 'gongkao', '运算', 'kp-xc-tutui-style-op', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"运算"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"核心结论：","marks":[{"type":"bold"}]},{"type":"text","text":"元素组成相似，相同线条/区域重复出现 → 考虑样式运算。三大运算：加减同异、黑白运算、定义叠加。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、题型识别"}]},{"type":"columns","attrs":{"cols":2},"content":[{"type":"column","attrs":{"index":0},"content":[{"type":"paragraph","content":[{"type":"text","text":"图形特征","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"元素组成相似"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"相同线条重复出现"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"轮廓和分割区域相同，颜色不同"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"九宫格或两组式出题"}]}]}]}]},{"type":"column","attrs":{"index":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"运算类型","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"加减同异：线条相加/相减/求同/求异"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"黑白运算：黑白块按位置叠加"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"定义叠加：自定义运算规则"}]}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、核心规律"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"求同：保留两图相同的部分"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"求异：保留两图不同的部分"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"相加：两图叠加在一起"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"相减：去掉两图相同的部分"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"黑白运算：黑+黑=黑，白+白=白，黑+白=?（需从题目推导）"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"三、解题步骤"}]},{"type":"textDiagram","attrs":{"language":"mermaid"},"content":[{"type":"text","text":"flowchart TD\n    A[元素相似] --> B{相同线条重复?}\n    B -->|是| C[考虑加减同异]\n    B -->|否| D{轮廓相同颜色不同?}\n    D -->|是| E[考虑黑白运算]\n    D -->|否| F[考虑其他规律]\n    C --> G[图1与图2运算=图3]\n    E --> H[从已知推出运算规则]\n    G --> I[代入验证]\n    H --> I"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"四、真题精讲"}]},{"type":"paragraph","content":[{"type":"text","text":"【例题】九宫格中，第一行图 1 与图 2 求异后得到图 3。","marks":[{"type":"bold"}]}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"观察：元素相似，相同线条重复出现 → 加减同异"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"第一行：图 1 求异 图 2 = 图 3（保留不同部分）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"第二行验证成立 → 第三行应用相同规律"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"五、易错点"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fef2f2","borderColor":"#ef4444","icon":"⚠️"},"content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"黑白运算的规则不是固定的，必须从题目中推导，不要想当然"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"求同和求异容易搞混：求同 = 保留相同的，求异 = 保留不同的"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"运算和旋转翻转可以复合出现"}]}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"刷题建议：","marks":